(7706653, 1265693, 68504, '<td valign="top">tempting to say that this is overdone, over sentimental, but the whole is really rather fetching.</td>', 'tempting to say that this is overdone, over sentimental, but the whole is really rather fetching.', '2021-11-14 23:42:34.000000', NULL, 1),
(7706655, 1265667, 173844, '<td valign="top">Highly effective depiction of inner memory, sinuous pathways and chopped up flashes.  Some are still green and fresh, others seemingly dried and gone, but never really so.</td>', 'Highly effective depiction of inner memory, sinuous pathways and chopped up flashes.  Some are still green and fresh, others seemingly dried and gone, but never really so.', '2021-11-14 23:44:55.000000', NULL, 1),
