(7706657, 1265651, 68504, '<td valign="top">oh dear. he certainly won''t come now. fireplace too clean.</td>', 'oh dear. he certainly won''t come now. fireplace too clean.', '2021-11-14 23:46:06.000000', NULL, 1),
(7706658, 1265687, 68504, '<td valign="top">the menace of memory.</td>', 'the menace of memory.', '2021-11-14 23:46:42.000000', NULL, 1),
(7706660, 1265687, 173844, '<td valign="top">Here are both hulking memories and the sparkly flashes that can surface at any time, however unlikely.  Rather than through a glass darkly, it looks like here it''s through a clear but obscuring sheet of plastic.  Interesting take, imaginative.  I like the muddled haziness of it.</td>', 'Here are both hulking memories and the sparkly flashes that can surface at any time, however unlikely.  Rather than through a glass darkly, it looks like here it''s through a clear but obscuring sheet of plastic.  Interesting take, imaginative.  I like the muddled haziness of it.', '2021-11-14 23:51:00.000000', NULL, 1),
(7706661, 1265676, 173844, '<td valign="top">Sensitive portrayal of the aching for a lost love one.  That it''s an ordinary, fine day imparts the sense that this missing person is daily in one''s thoughts.  I like how her translucence is such that she''s almost there, almost.</td>', 'Sensitive portrayal of the aching for a lost love one.  That it''s an ordinary, fine day imparts the sense that this missing person is daily in one''s thoughts.  I like how her translucence is such that she''s almost there, almost.', '2021-11-14 23:56:06.000000', NULL, 1),
